parameters.jsonBody:
={
  "contents": [{
    "parts": [{
      "text": "You are an elite viral short-form video creator. Generate a high-retention 30-second video script about emerging autonomous AI tech. Return ONLY raw valid JSON with keys: topic, hook, script (around 65 words, punchy sentences), caption (with hashtags), visual_prompts (array of 4 vivid vertical background scene descriptions). Do not use markdown backticks."
    }]
  }]
}

parameters.jsCode:
const text = $json.candidates[0].content.parts[0].text;
let parsed;
try {
  const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleanText);
} catch (e) {
  parsed = {
    topic: "Autonomous AI Agency Revolution",
    hook: "Why manual business operations are dead in 2026",
    script: "Running an agency used to take ten employees and five thousand dollars a month in SaaS tools. Today, autonomous AI systems handle lead intake, video production, and site deployment simultaneously. The future belongs to those who build zero-marginal-cost ecosystems.",
    caption: "The autonomous business revolution is here. Are you adapting? 🚀 #ai #automation #tech #future #business",
    visual_prompts: [
      "Futuristic glowing AI brain core with fiber optic neon data streams",
      "High tech modern digital control room with sleek glass UI monitors",
      "Autonomous robotic assembly line crafting glowing holographic circuits",
      "Minimalist dark executive penthouse office looking out at a cybernetic city skyline"
    ]
  };
}
return parsed;
